import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css'; // Make sure to import your CSS file
import BASE_URL from '../../apiConfig'; // Adjust path based on your file structure

const ThresholdTable = () => {
  const [values, setValues] = useState({});
  const [showValues, setShowValues] = useState(false);
  const deviceId = localStorage.getItem('selectedDeviceId');
  const serialNumber = localStorage.getItem('selectedSerialNumber'); 


  const thresholds = [
    { no: 1, name: "Threshold for voltage sag", code: "(3,1-0: 12.3.... )", unit: "V" },
    { no: 2, name: "Time threshold for voltage sag", code: "(3,1-0: 12.4.... )", unit: "s" },
    { no: 3, name: "Threshold for voltage swell", code: "(3,1-0: 12.3.... )", unit: "V" },
    { no: 4, name: "Time Threshold for voltage swell", code: "(3,1-0:12.4...... )", unit: "s" },
    { no: 5, name: "Threshold for missing voltage (voltage cut)", code: "(3,1-0: 12.3.... )", unit: "V" },
    { no: 6, name: "Time Threshold for missing voltage (voltage cut)", code: "(3,1-0:12.4...... )", unit: "s" },
    { no: 7, name: "Threshold for current bypass", code: "(3,1-0: 11.3.... )", unit: "%" },
    { no: 8, name: "Time Threshold for current bypass", code: "(3,1-0: 11.4.... )", unit: "s" },
    { no: 9, name: "Threshold low power factor", code: "(3,1-0: 13.3.... )", unit: "" },
    { no: 10, name: "Time Threshold low power factor", code: "(3,1-0:13.4....)", unit: "s" },
    { no: 11, name: "Time threshold for magnetic disturbance", code: "( 3,1-0:96.8....)", unit: "s" },
    { no: 12, name: "Time threshold for current reverse", code: "(3,0-0.96.8....)", unit: "s" },
    { no: 13, name: "Clock adjustment event deviation", code: "(3,1-0.0.9.... )", unit: "s" },
    { no: 14, name: "Time threshold for long power failure", code: "(3,0-0:96.7... )", unit: "s" },
  ];
  

  

 
  const fetchValues = async () => {
    try {
      const response = await axios.get(`${BASE_URL}/thresholds/${serialNumber}/`);
      console.log('API Response:', response.data); // Log the response
      const fetchedValues = response.data.thresholds.reduce((acc, item) => {
        acc[item.name] = item.value;
        return acc;
      }, {});
      console.log('Fetched Values:', fetchedValues); // Log the processed values
      setValues(fetchedValues);
    } catch (error) {
      console.error('Error fetching values:', error);
    }
  };
  

  const handleButtonClick = () => {
    setShowValues(true);
    fetchValues()
  };

  return (
    <div className="threshold-table-container">
      <button onClick={handleButtonClick}>Get Values</button>
      <table className="threshold-table">
        <thead>
          <tr>
            <th className="threshold-table-header">Checked</th>
            <th className="threshold-table-header">No</th>
            <th className="threshold-table-header">Name</th>
            <th className="threshold-table-header">Code</th>
            <th className="threshold-table-header">Value</th>
            <th className="threshold-table-header">Unit</th>
          </tr>
        </thead>
        <tbody>
          {thresholds.map((threshold) => (
            <tr key={threshold.no} className="threshold-table-row">
              <td className="threshold-table-cell">
                <input type="checkbox" />
              </td>
              
              <td className="threshold-table-cell">{threshold.no}</td>
              <td className="threshold-table-cell">{threshold.name}</td>
              <td className="threshold-table-cell">{threshold.code}</td>
              <td className="threshold-table-cell">{showValues ? values[threshold.name] || '' : ''}</td>
              <td className="threshold-table-cell">{threshold.unit}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ThresholdTable;

