function InstantaneousReadings() {
  const [checkedItems, setCheckedItems] = useState({});
  const [streamValues, setStreamValues] = useState({});
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  
 const serialNumber = localStorage.getItem('selectedSerialNumber');
 const data = [
    { name: 'Instantaneous voltage L1', code: '(3,1-0:32.7.0.255)', value: '' },
    { name: 'Average voltage L1', code: '(3,1-0:32.24.0.255)', value: '' },
    { name: 'Instantaneous current L1', code: '(3,1-0:31.7.0.255)', value: '' },
    { name: 'Instantaneous current L0', code: '(3,1-0:91.7.0.255)', value: '' },
    { name: 'Average current L1', code: '(3,1-0:31.24.0.255)', value: '' },
    { name: 'Sliding average current L1', code: '(3,1-0:31.40.0.250)', value: '' },
    { name: 'Instantaneous import active power (+A)', code: '(3,1-0:1.7.0.255)', value: '' },
    { name: 'Instantaneous export active power (-A)', code: '(3,1-0:2.7.0.255)', value: '' },
    { name: 'Instantaneous active power (+A/-A)', code: '(3,1-0:15.7.0.255)', value: '' },
    { name: 'Instantaneous import reactive power (+R)', code: '(3,1-0:3.7.0.255)', value: '' },
    { name: 'Instantaneous export reactive power (-R)', code: '(3,1-0:4.7.0.255)', value: '' },
    { name: 'Instantaneous import apparent power (+VA)', code: '(3,1-0:9.7.0.255)', value: '' },
    { name: 'Instantaneous export apparent power (-VA)', code: '(3,1-0:10.7.0.255)', value: '' },
    { name: 'Instantaneous power factor (+A/+VA)', code: '(3,1-0:13.7.0.255)', value: '' },
    { name: 'Instantaneous supply frequency', code: '(3,1-0:14.7.0.255)', value: '' },
    { name: 'External battery voltage', code: '(3,0-1:96.8.0.255)', value: '' },
  ];


  const controllerRef = useRef(null);

  const handleCheck = (name) => {
    setCheckedItems((prev) => ({
      ...prev,
      [name]: !prev[name],
    }));
  };

  const handleRead = async () => {
    setError(null);
    console.log("hello")

    // Abort any previous running stream
    if (controllerRef.current) {
      try { controllerRef.current.abort(); } catch (e) {}
    }

    const selectedParams = [];

    (data || []).forEach(item => {
      if (checkedItems && checkedItems[item.name]) {
        const cleanCode = (item.code || '')
          .replace(/[()]/g, '')
          .replace(/-/g, '.')
          .replace(/:/g, '.')
          .replace(/\.{2,}/g, '.');
        const parts = cleanCode.split(',');
        const obis = (parts[1] || parts[0] || '').trim();
        if (obis) selectedParams.push({ obis_code: obis, attribute_index: '2' });
      }
    });

    if (selectedParams.length === 0) {
      alert('Please select at least one item to read.');
      return;
    }

    const payload = {
      serial_number: serialNumber,
      action: 'read_obis',
      parameters: selectedParams,
    };

    console.log('payload', payload);

    controllerRef.current = new AbortController();
    setLoading(true);

    try {
      const res = await fetch(`${BASE_URL}/api/Instantaneoustream_obis/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: controllerRef.current.signal,
      });

      if (!res.ok) throw new Error(`Server returned ${res.status}`);

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const chunks = buffer.split('\n\n');
        buffer = chunks.pop();

        for (let chunk of chunks) {
          if (!chunk.startsWith('data:')) continue;

          try {
            const msg = JSON.parse(chunk.replace(/^data:\s*/, ''));
            if (msg && msg.obis_code) {
              setStreamValues((prev) => ({
                ...prev,
                [msg.obis_code]: msg.value,
              }));
            }
          } catch (e) {
            console.error('Error parsing SSE chunk', e);
          }
        }
      }
    } catch (err) {
      console.error('Streaming error', err);
      setError(err.message || 'Error streaming data');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Instantaneous Readings</h2>

      {error && <p style={{ color: 'red' }}>{error}</p>}
       <button onClick={handleRead} disabled={loading}>
        {loading ? 'Reading...' : 'Read Selected'}
      </button>

      <table border="1" cellPadding="6">
        <thead>
          <tr>
            <th>Select</th>
            <th>No</th>
            <th>Name</th>
            <th>Code</th>
            <th>Value</th>
          </tr>
        </thead>
        <tbody>
          {(data || []).map((item, index) => {
            const cleanCode = (item.code || '')
              .replace(/[()]/g, '')
              .replace(/-/g, '.')
              .replace(/:/g, '.')
              .replace(/\.{2,}/g, '.');
            const parts = cleanCode.split(',');
            const obis = (parts[1] || parts[0] || '').trim();

            return (
              <tr key={item.name}>
                <td>
                  <input
                    type="checkbox"
                    checked={!!checkedItems[item.name]}
                    onChange={() => handleCheck(item.name)}
                  />
                </td>
                <td>{index + 1}</td>
                <td>{item.name}</td>
                <td>{obis}</td>
                <td>{streamValues[obis] || ''}</td>
              </tr>
            );
          })}
        </tbody>
      </table>

     
    </div>
  );
}









 function MonthlyBillingDashboard() {
  const [billingProfile, setBillingProfile] = useState("");
  const [selectMode, setSelectMode] = useState("");
  const [fromValue, setFromValue] = useState("");
  const [toValue, setToValue] = useState("");
  const [rows, setRows] = useState([
  
  ]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const controllerRef = useRef(null);

  // helper to convert "datetime-local" string to ISO timezone-aware string
  const toISOStringLocal = (localDatetime) => {
    if (!localDatetime) return null;
    const d = new Date(localDatetime);
    return d.toISOString();
  };

  const handleSelectChange = (event) => {
    const { id, value } = event.target;
    if (id === "billing-profile") {
      setBillingProfile(value);
    } else if (id === "select-mode") {
      setSelectMode(value);
      setFromValue("");
      setToValue("");
    }
  };

  // merge incoming item into rows by `no`. If not present, push at end.
  const upsertRow = (incoming) => {
    setRows(prev => {
      const idx = prev.findIndex(r => Number(r.no) === Number(incoming.no));
      if (idx >= 0) {
        const copy = [...prev];
        // keep previous keys but overwrite with incoming fields
        copy[idx] = { ...copy[idx], ...incoming };
        return copy;
      } else {
        return [...prev, incoming];
      }
    });
  };

  const validateAndBuildPayload = () => {
    const payload = { serial_number: localStorage.getItem("selectedSerialNumber") || "MTR1", mode: selectMode || "all", stream: true };

    if (selectMode === "entry") {
      // allow single entry (fromValue) or range (fromValue & toValue)
      if (!fromValue) {
        alert("Please enter From entry number");
        return null;
      }
      payload.from_entry = Number(fromValue);
      if (toValue) payload.to_entry = Number(toValue);
    } else if (selectMode === "range") {
      if (!fromValue || !toValue) {
        alert("Please provide both From and To date/times for range.");
        return null;
      }
      
      // before POST
      payload.from_date = fromValue ? new Date(fromValue).toISOString() : null;
      payload.to_date   = toValue   ? new Date(toValue).toISOString()   : null;


    } else if (selectMode === "latest") {
      // nothing extra required
    } else {
      // all
    }
    return payload;
  };

  // Start streaming read
  const handleRead = async () => {
    setError(null);
    const payload = validateAndBuildPayload();
    if (!payload) return;

    // abort existing stream
    if (controllerRef.current) {
      try { controllerRef.current.abort(); } catch (e) { /* ignore */ }
    }

    controllerRef.current = new AbortController();
    setLoading(true);

    try {
      const res = await fetch(`${BASE_URL}/api/monthly_billing/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        signal: controllerRef.current.signal
      });

      if (!res.ok) throw new Error(`Server returned ${res.status}`);
      

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });

        // server splits events with two newlines ("\n\n")
        const chunks = buffer.split("\n\n");
        buffer = chunks.pop(); // leftover

        for (let chunk of chunks) {
          if (!chunk.startsWith("data:")) continue;
          try {
            const msg = JSON.parse(chunk.replace(/^data:\s*/, ""));
            // msg should be an object like:
            // { no, date, reading_datetime, active_import, active_export, ... }
            if (msg && typeof msg === "object") {
              // normalize keys to match our table: use lower_snake keys
              const incoming = {
                no: msg.no ?? msg.entry_no ?? msg.id,
                date: msg.date ?? (msg.reading_datetime ? new Date(msg.reading_datetime).toLocaleString() : ""),
                reading_datetime: msg.reading_datetime ?? msg.date,
                active_import: msg.active_import ?? msg.activeImport ?? msg.active_import,
                active_export: msg.active_export ?? msg.activeExport ?? msg.active_export,
                reactive_import: msg.reactive_import ?? msg.reactiveImport ?? msg.reactive_import,
                reactive_export: msg.reactive_export ?? msg.reactiveExport ?? msg.reactive_export,
                residual: msg.residual ?? msg.residual,
                energy_used: msg.energy_used ?? msg.energyUsed ?? msg.energy_used
              };
              upsertRow(incoming);
            }
          } catch (e) {
            console.warn("SSE chunk parse error", e);
          }
        }
      }
    } catch (err) {
      if (err.name === "AbortError") {
        console.log("Stream aborted");
      } else {
        console.error("Read stream error", err);
        setError(err.message || "Read failed");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleStop = () => {
    if (controllerRef.current) {
      try {
        controllerRef.current.abort();
        controllerRef.current = null;
      } catch (e) {}
    }
    setLoading(false);
  };

  // Save currently displayed rows to backend (expects an API to receive these)
  const handleSave = async () => {
    setError(null);
    const serial_number = localStorage.getItem("selectedSerialNumber") || "MTR1";
    const payload = {
      serial_number,
      readings: rows.map(r => ({
        entry_no: r.no,
        reading_datetime: r.reading_datetime || (new Date(r.date).toISOString()),
        active_import: r.active_import,
        active_export: r.active_export,
        reactive_import: r.reactive_import,
        reactive_export: r.reactive_export,
        residual: r.residual,
        energy_used: r.energy_used
      }))
    };

    try {
      // Endpoint must be implemented on backend to accept and save this data
      const resp = await axios.post(`${BASE_URL}/api/monthly_billing/save_readings/`, payload, { headers: { "Content-Type": "application/json" } });
      alert("Saved: " + (resp.data?.message ?? "OK"));
    } catch (e) {
      console.error("Save failed", e);
      setError(e.response?.data?.error || e.message || "Save failed");
      alert("Save failed: " + (e.response?.data?.error || e.message));
    }
  };

  const handleRefresh = () => {
    // reset rows to empty or re-load from backend (here we simply clear and re-add initial demo)
    setRows([]);
    // optionally auto-trigger a read for current mode
    // handleRead();
    alert("Refreshed local table. To fetch live data, click Read.");
  };

  return (
    <div className="dashboard-container" style={{ padding: 12 }}>
      <div style={{ width: "100%", marginBottom: 12 }}>
        <label htmlFor="select-mode">Select Mode Entries:</label>
        <select id="select-mode" value={selectMode} onChange={handleSelectChange} style={{ width: "100%", marginTop: 4 }}>
          <option value="">-- Select --</option>
          <option value="all">All</option>
          <option value="entry">Entry</option>
          <option value="range">Range (date)</option>
          <option value="latest">Latest</option>
        </select>
      </div>

      <div className="controls-section" style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 12 }}>
        <div className="control-group">
          <label>Entries: in use</label>
          <input type="text" readOnly value={rows.length || 0} />
        </div>

        <div className="control-group">
          <label>Profile Entries:</label>
          <input type="text" readOnly value={rows.length || 0} />
        </div>

        {selectMode === "entry" && (
          <>
            <div className="control-group">
              <label>From (entry no)</label>
              <input type="number" value={fromValue} onChange={e => setFromValue(e.target.value)} />
            </div>
            <div className="control-group">
              <label>To (entry no)</label>
              <input type="number" value={toValue} onChange={e => setToValue(e.target.value)} />
            </div>
          </>
        )}

        {selectMode === "range" && (
          <>
            <div className="control-group">
              <label>From (date/time)</label>
              <input type="datetime-local" value={fromValue} onChange={e => setFromValue(e.target.value)} />
            </div>
            <div className="control-group">
              <label>To (date/time)</label>
              <input type="datetime-local" value={toValue} onChange={e => setToValue(e.target.value)} />
            </div>
          </>
        )}
      </div>

      <div style={{ marginBottom: 12 }}>
        <button onClick={handleRead} disabled={loading} style={{ marginRight: 8 }}>{loading ? "Reading..." : "Read"}</button>
        <button onClick={handleStop} disabled={!loading} style={{ marginRight: 8 }}>Stop</button>
        <button onClick={handleSave} style={{ marginRight: 8 }}>Save</button>
        <button onClick={handleRefresh}>Refresh</button>
        {error && <div style={{ color: "red", marginTop: 8 }}>{error}</div>}
      </div>

      <table className="billing-table" style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>No</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Date</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Active Import</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Active Export</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Reactive Import</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Reactive Export</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Residual</th>
            <th style={{ border: "1px solid #ddd", padding: 6 }}>Energy Used</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr>
              <td colSpan={8} style={{ padding: 12, textAlign: "center" }}>No rows to display</td>
            </tr>
          )}
          {rows.map(row => (
            <tr key={row.no}>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.no}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.date}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.active_import}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.active_export}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.reactive_import}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.reactive_export}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.residual}</td>
              <td style={{ border: "1px solid #eee", padding: 6 }}>{row.energy_used}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}



